<script>
Webflow.push(function () {
  // Skip inside the Designer/Editor canvas â€” Webflow.push fires there too,
  // and you don't want hover tweens fighting with the visual builder.
  if (window.Webflow && Webflow.env && Webflow.env("editor")) return;

  var wrap = document.querySelector(".fda-planning-card-wrap-v2");
  if (!wrap || typeof gsap === "undefined") return;

  var DURATION = 0.5;
  var EASE = "power2.out";

  var cards = Array.prototype.slice.call(wrap.querySelectorAll(".fda-planning-card-v2"));

  var items = cards.map(function (card) {
    return {
      card: card,
      bg: card.querySelector(
        "[planning-background], [planning-background-active], .fda-planning-card-choose-bg"
      ),
      title: card.querySelector(
        "[plan-text-title], [plan-text-title-active], .fda-text-style-h4"
      ),
      copy: card.querySelector(
        "[plan-text-paragraph], [plan-text-paragraph-active], .fda-gap-none"
      ),
      numberWrap: card.querySelector(
        "[planing-number], [planing-number-active], .fda-planning-number-tag"
      ),
      imageWrap: card.querySelector(
        "[planing-image], [planing-image-active], .fda-planning-right-image"
      )
    };
  });

  // Whichever card already has fda-active in the markup is the default.
  var initialIndex = items.findIndex(function (item) {
    return item.card.classList.contains("fda-active");
  });
  if (initialIndex === -1) initialIndex = 0;

  // Sample the real inactive text colors from CSS, off a non-active card,
  // so "deactivate" always returns to whatever the stylesheet defines.
  var sample = items[initialIndex === 0 ? 1 : 0] || items[0];
  var defaultTitleColor = sample.title ? getComputedStyle(sample.title).color : "";
  var defaultCopyColor = sample.copy ? getComputedStyle(sample.copy).color : "";

  function setActive(item, animate) {
    var method = animate ? gsap.to : gsap.set;
    var dur = animate ? DURATION : 0;

    if (item.bg) method(item.bg, { opacity: 1, duration: dur, ease: EASE, overwrite: "auto" });
    if (item.title) method(item.title, { color: "#ffffff", duration: dur, ease: EASE, overwrite: "auto" });
    if (item.copy) method(item.copy, { color: "#ffffff", duration: dur, ease: EASE, overwrite: "auto" });
    if (item.numberWrap) method(item.numberWrap, { opacity: 0, duration: dur, ease: EASE, overwrite: "auto" });
    if (item.imageWrap) method(item.imageWrap, { opacity: 1, duration: dur, ease: EASE, overwrite: "auto" });

    item.card.classList.add("fda-active");
    if (item.bg) item.bg.classList.add("fda-active");
    if (item.title) item.title.classList.add("fda-active");
    if (item.copy) item.copy.classList.add("fda-active", "fda-color-white");
  }

  function setInactive(item, animate) {
    var method = animate ? gsap.to : gsap.set;
    var dur = animate ? DURATION : 0;

    if (item.bg) method(item.bg, { opacity: 0, duration: dur, ease: EASE, overwrite: "auto" });

    if (item.title) {
      method(item.title, {
        color: defaultTitleColor,
        duration: dur,
        ease: EASE,
        overwrite: "auto",
        onComplete: function () { gsap.set(item.title, { clearProps: "color" }); }
      });
    }
    if (item.copy) {
      method(item.copy, {
        color: defaultCopyColor,
        duration: dur,
        ease: EASE,
        overwrite: "auto",
        onComplete: function () { gsap.set(item.copy, { clearProps: "color" }); }
      });
    }
    if (item.numberWrap) method(item.numberWrap, { opacity: 1, duration: dur, ease: EASE, overwrite: "auto" });
    if (item.imageWrap) method(item.imageWrap, { opacity: 0, duration: dur, ease: EASE, overwrite: "auto" });

    item.card.classList.remove("fda-active");
    if (item.bg) item.bg.classList.remove("fda-active");
    if (item.title) item.title.classList.remove("fda-active");
    if (item.copy) item.copy.classList.remove("fda-active", "fda-color-white");
  }

  function activateOnly(index, animate) {
    items.forEach(function (item, i) {
      if (i === index) setActive(item, animate);
      else setInactive(item, animate);
    });
  }

  function deactivateAll(animate) {
    items.forEach(function (item) { setInactive(item, animate); });
  }

  // gsap.matchMedia() is GSAP's own recommended responsive pattern â€” it
  // replaces manual window.matchMedia + addEventListener bookkeeping,
  // and auto-reverts any tweens created inside a block once that block's
  // condition stops matching (e.g. resizing from desktop to mobile).
  var mm = gsap.matchMedia();

  mm.add("(min-width: 992px)", function () {
    // ---- DESKTOP ----
    activateOnly(initialIndex, false);

    var enterHandlers = items.map(function (item, index) {
      var handler = function () { activateOnly(index, true); };
      item.card.addEventListener("mouseenter", handler);
      return handler;
    });

    function handleLeave() { activateOnly(initialIndex, true); }
    wrap.addEventListener("mouseleave", handleLeave);

    // Returned cleanup runs the moment this condition stops matching â€”
    // DOM listeners aren't part of GSAP's tween revert, so remove manually.
    return function () {
      items.forEach(function (item, index) {
        item.card.removeEventListener("mouseenter", enterHandlers[index]);
      });
      wrap.removeEventListener("mouseleave", handleLeave);
    };
  });

  mm.add("(max-width: 991px)", function () {
    // ---- TABLET / MOBILE ----
    // All cards sit deactivated, no hover/tap interaction.
    deactivateAll(false);
  });
});
</script><script src="{{ asset('js/custom-animations.js') }}"></script>
